PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investor ?investorLabel
WHERE {
  ?investor a wm:Investor ;
            wm:riskTolerance ?rt ;
            rdfs:label ?investorLabel .
  FILTER(LCASE(STR(?rt)) = "aggressive")

  ?goal a wm:InvestmentGoal ;
        wm:belongsToInvestor ?investor ;
        wm:shortfall ?sf .
  FILTER(xsd:decimal(?sf) > 0)

  ?hold a wm:PortfolioHolding ;
        wm:heldByInvestor ?investor ;
        wm:investmentName ?iname .
  FILTER(CONTAINS(LCASE(STR(?iname)), "gold"))

  ?ph a wm:PortfolioHealth ;
      wm:healthOfInvestor ?investor ;
      wm:riskScore ?rs .
  FILTER(xsd:decimal(?rs) > 60)

  ?sa a wm:SectorAllocation ;
      wm:allocationOfInvestor ?investor ;
      wm:allocationPct ?ap .
  FILTER(xsd:decimal(?ap) > 30)
}

